#!/usr/bin/env python3
"""Replace Linear ticket IDs in Markdown with [ID Title](url) links.

Usage: pbpaste | ./linearize.py | pbcopy
"""

import json
import re
import sys
import urllib.request

LINEAR_API_KEY = "lin_api_..."
TEAM_KEYS = ["ENG"]
BATCH_SIZE = 50

TICKET = rf"\b(?:{'|'.join(map(re.escape, TEAM_KEYS))})-\d+\b"

# Protected regions are matched first so ticket IDs inside them are left alone.
TOKEN = re.compile(
    rf"""
    (?P<fence>^[ \t]*(?P<fence_mark>```|~~~)(?s:.*?)(?:^[ \t]*(?P=fence_mark)|\Z))
  | (?P<code>(?P<ticks>`+)(?s:.+?)(?P=ticks))
  | (?P<link>!?\[[^\]\n]*\](?:\([^)\n]*\)|\[[^\]\n]*\])?)
  | (?P<autolink><[a-z][a-z0-9+.-]*:[^>\s]*>)
  | (?P<url>\bhttps?://\S+)
  | (?P<ticket>{TICKET})
    """,
    re.MULTILINE | re.VERBOSE | re.IGNORECASE * 0,
)


def find_ticket_ids(text: str) -> list[str]:
    ids = [m.group("ticket") for m in TOKEN.finditer(text) if m.group("ticket")]
    return list(dict.fromkeys(ids))


def fetch_issues(ids: list[str]) -> dict[str, dict]:
    issues: dict[str, dict] = {}
    for start in range(0, len(ids), BATCH_SIZE):
        batch = ids[start : start + BATCH_SIZE]
        fields = "\n".join(
            f"i{n}: issue(id: {json.dumps(ticket_id)}) {{ identifier title url }}"
            for n, ticket_id in enumerate(batch)
        )
        request = urllib.request.Request(
            "https://api.linear.app/graphql",
            data=json.dumps({"query": f"query {{ {fields} }}"}).encode(),
            headers={
                "Content-Type": "application/json",
                "Authorization": LINEAR_API_KEY,
            },
        )
        # Linear answers unknown IDs with partial data plus errors, not an HTTP failure.
        with urllib.request.urlopen(request) as response:
            data = json.load(response).get("data") or {}
        for n, ticket_id in enumerate(batch):
            issue = data.get(f"i{n}")
            if issue:
                issues[ticket_id] = issue
            else:
                print(f"warning: {ticket_id} not found", file=sys.stderr)
    return issues


def escape_link_text(text: str) -> str:
    return re.sub(r"([\\\[\]])", r"\\\1", text)


def linkify(text: str, issues: dict[str, dict]) -> str:
    def replace(match: re.Match) -> str:
        ticket_id = match.group("ticket")
        issue = issues.get(ticket_id) if ticket_id else None
        if not issue:
            return match.group(0)
        label = escape_link_text(f"{ticket_id} {issue['title']}")
        return f"[{label}]({issue['url']})"

    return TOKEN.sub(replace, text)


def main() -> None:
    text = sys.stdin.read()
    ids = find_ticket_ids(text)
    issues = fetch_issues(ids) if ids else {}
    sys.stdout.write(linkify(text, issues))


if __name__ == "__main__":
    main()

